      const preflightHeaders = { "method.response.header.Access-Control-Allow-Origin": quote(origin), "method.response.header.Access-Control-Allow-Methods": quote(allowedMethods), "method.response.header.Access-Control-Allow-Headers": quote(allowHeaders), ...(credentials ? { "method.response.header.Access-Control-Allow-Credentials": "'true'" } : {}), ...(expose ? { "method.response.header.Access-Control-Expose-Headers": quote(expose) } : {}) }; const declared = Object.fromEntries(Object.keys(preflightHeaders).map(name => [name, true]));
      await rest(`/restapis/${apiId}/resources/${selected.id}/methods/OPTIONS`, "PUT", { authorizationType: "NONE" }); await rest(`/restapis/${apiId}/resources/${selected.id}/methods/OPTIONS/responses/200`, "PUT", { responseParameters: declared }); await rest(`/restapis/${apiId}/resources/${selected.id}/methods/OPTIONS/integration`, "PUT", { type: "MOCK", httpMethod: "OPTIONS", requestTemplates: { "application/json": "{\"statusCode\":200}" }, contentHandling: "CONVERT_TO_TEXT" }); await rest(`/restapis/${apiId}/resources/${selected.id}/methods/OPTIONS/integration/responses/200`, "PUT", { statusCode: "200", responseParameters: preflightHeaders });
      let proxyOwned = 0; const actualHeaders = { "method.response.header.Access-Control-Allow-Origin": quote(origin), ...(credentials ? { "method.response.header.Access-Control-Allow-Credentials": "'true'" } : {}), ...(expose ? { "method.response.header.Access-Control-Expose-Headers": quote(expose) } : {}) };
      for (const method of selectedMethods) { const configuration = selected.resourceMethods?.[method]; if (!configuration || configuration.methodIntegration?.type?.endsWith("_PROXY")) { proxyOwned++; continue; } for (const response of Object.values(configuration.methodResponses ?? {})) { await rest(`/restapis/${apiId}/resources/${selected.id}/methods/${method}/responses/${response.statusCode}`, "PUT", { responseParameters: { ...(response.responseParameters ?? {}), ...Object.fromEntries(Object.keys(actualHeaders).map(name => [name, true])) }, responseModels: response.responseModels ?? {} }); } for (const response of Object.values(configuration.methodIntegration?.integrationResponses ?? {})) { await rest(`/restapis/${apiId}/resources/${selected.id}/methods/${method}/integration/responses/${response.statusCode}`, "PUT", { statusCode: response.statusCode, selectionPattern: response.selectionPattern, responseParameters: { ...(response.responseParameters ?? {}), ...actualHeaders }, responseTemplates: response.responseTemplates ?? {}, contentHandling: response.contentHandling }); } }
