        await rest(`/restapis/${apiId}/resources/${resourceId}/methods/${method}/integration/responses/${status}`, "PUT", { statusCode: status, selectionPattern: data.get("selection") || undefined, responseTemplates: JSON.parse(String(data.get("responseTemplates") || "{}")) });
        toast("Method pipeline and validation updated");
